Tool response:
Tool: create_contract_accessorial_charge
Description: Create a new contract accessorial charge
Parameters:
    {
      "type": "object",
      "properties": {
        "contract_id": {
          "type": "integer",
          "title": "Contract Id"
        },
        "accessorial_charge_code_id": {
          "type": "integer",
          "title": "Accessorial Charge Code Id"
        },
        "rate": {
          "type": "number",
          "title": "Rate"
        },
        "rate_unit": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Rate Unit",
          "default": "per_occurrence"
        },
        "max_weight_lbs": {
          "anyOf": [
            {
              "type": "number"
            },
            {
              "type": "null"
            }
          ],
          "title": "Max Weight Lbs"
        },
        "freight_class": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Freight Class"
        },
        "zip_code_start": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Zip Code Start"
        },
        "zip_code_end": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Zip Code End"
        },
        "effective_date": {
          "type": "string",
          "title": "Effective Date"
        },
        "expiration_date": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Expiration Date"
        }
      },
      "required": [
        "contract_id",
        "accessorial_charge_code_id",
        "rate",
        "effective_date"
      ]
    }

